import re
with open(GRAPH_TTL) as f: data=f.read()
patterns=[
    r'bldg:(Zone_F3_Z01\.CO2_Sensor) a brick:CO2_Sensor ;(.*?)(?=\n\n)',
    r'bldg:(Zone_F3_Z01_Electric_Power_Sensor) a brick:Electric_Power_Sensor ;(.*?)(?=\n\n)',
]
for p in patterns:
    for m in re.finditer(p, data):
        ts=re.search(r'tsref:([\w-]+)', m.group(2))
        print(m.group(1), ts.group(1) if ts else None)

import re
with open(GRAPH_TTL) as f: data=f.read()
# gather per-zone CO2, Power, Zone_Temp, VAV supply flow sensors
pat=r'bldg:(Zone_(\w+)\.Zone_Air_Temperature_Sensor|Zone_(\w+)\.CO2_Sensor|Zone_(\w+)_Electric_Power_Sensor|VAV_(\w+)\.Supply_Air_Flow_Sensor) a brick:[A-Z_]+ ;(.*?)(?=\n\n)'
zones={}
for m in re.finditer(pat, data):
    name=m.group(1)
    ts=re.search(r'tsref:([\w-]+)', m.group(6))
    zid_re=re.search(r'(F\d+)', name)
    if zid_re:
        zid=zid_re.group(1)
        zones.setdefault(zid, []).append((name, ts.group(1) if ts else None))
for z in sorted(zones):
    for n,t in zones[z]:
        print(z, n, t)

